<script setup lang="ts">
import {ref,onUnmounted} from 'vue'
import {accountApi} from '../platform/account'
import {contentOperations,fetchPublicResources,type ContentVersion,type ContentAudit} from '../platform/resources'
import {validatePublicPackage,type PublicPackage} from '../domain/resources'
const emit=defineEmits<{close:[]}>()
const verified=ref(false),busy=ref(false),error=ref(''),message=ref(''),draft=ref(''),preview=ref<PublicPackage|null>(null),versions=ref<ContentVersion[]>([]),audit=ref<ContentAudit[]>([]),revision=ref(0),current=ref(''),target=ref('')
let disposed=false,accountId='',epoch=0;onUnmounted(()=>{disposed=true;epoch++})
function clear(){verified.value=false;preview.value=null;versions.value=[];audit.value=[];draft.value='';target.value='';current.value='';accountId=''}
async function refresh(){const release=await fetchPublicResources();const history=await contentOperations.audit();const list=await contentOperations.versions();return {release,history,list}}
async function run(action?:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';const ticket=++epoch;try{const identity=await accountApi.me();if(disposed||ticket!==epoch)return;if(accountId&&accountId!==identity.account.id){clear();throw new Error('登录账户已变化，请重新核验运营权限')}
// The server is the authority; a family administrator does not imply content operator access.
await contentOperations.versions();if(disposed||ticket!==epoch)return;accountId=identity.account.id;if(action)await action();const data=await refresh();const now=await accountApi.me();if(disposed||ticket!==epoch)return;if(now.account.id!==accountId){clear();throw new Error('登录账户已变化，请重新核验运营权限')}
verified.value=true;versions.value=data.list;audit.value=data.history;revision.value=data.release.revision;current.value=data.release.package?.id||''
}catch(e){if(disposed||ticket!==epoch)return;clear();error.value=e instanceof Error?e.message:'无法核验运营权限'}finally{if(!disposed&&ticket===epoch)busy.value=false}}
function check(){error.value='';preview.value=null;try{const value:unknown=JSON.parse(draft.value);if(!validatePublicPackage(value))throw new Error('仅支持合法的公共卡片和场景，来源与许可必填，禁止私密资料和图片');preview.value=value}catch(e){error.value=e instanceof Error?e.message:'JSON 格式不正确'}}
async function publish(){const p=preview.value;if(!p||!verified.value)return;await run(async()=>{await contentOperations.publish(p);if(!disposed){preview.value=null;message.value=`已保存不可变版本 ${p.id}，尚未切换公开版本。`}})}
async function release(){const id=target.value,expected=revision.value;if(!id||!verified.value||busy.value)return;const result=await uni.showModal({title:'切换公共资源版本？',content:`当前发布修订 ${expected}，将切换为 ${id}。选择旧版本即回滚；已安装的本机资源不会被删除。`,confirmText:'确认切换'});if(disposed||!result.confirm||!verified.value||revision.value!==expected)return;await run(async()=>{await contentOperations.release(id,expected);if(!disposed)message.value=`已切换到 ${id}。`})}
</script>
<template><view class="content-operator"><view class="operator-heading"><text class="section-title">公共内容运营</text><button role="button" tabindex="0" class="outline-button" @click="emit('close')">关闭运营</button></view><text class="modal-copy">仅配置的运营账户可发布。普通家庭管理员不会自动获得发布权限。</text><button role="button" tabindex="0" class="outline-button" :disabled="busy" @click="run()">{{busy?'正在核验…':'核验运营权限并刷新'}}</button><template v-if="verified"><text>当前版本：{{current||'尚未发布'}} · 修订 {{revision}}</text><text class="form-label">公共资源 JSON</text><textarea v-model="draft" aria-label="公共资源版本 JSON" :maxlength="-1" placeholder="粘贴符合公共资源格式的 JSON；来源与许可必填" @input="preview=null"/><button role="button" tabindex="0" class="outline-button" :disabled="busy" @click="check">校验并预览版本</button><view v-if="preview" class="content-preview"><text>{{preview.title}} · {{preview.id}}</text><text>来源：{{preview.source}}</text><text>许可：{{preview.license}}</text><text v-for="c in preview.cards" :key="c.id">卡片 {{c.label}}：{{c.description}}</text><text v-for="s in preview.scenes" :key="s.id">场景 {{s.name}}：{{s.description}}</text><button role="button" tabindex="0" class="primary-button" :disabled="busy" @click="publish">保存此不可变版本</button></view><text class="section-title">发布或回滚</text><picker :range="versions.map(v=>v.id)" @change="target=versions[Number($event.detail.value)]?.id||''"><view class="filter-picker">{{target||'选择已保存版本'}} ▾</view></picker><button role="button" tabindex="0" class="outline-button" :disabled="busy||!target" @click="release">切换到所选版本</button><text class="section-title">最近切换审计</text><text v-for="entry in audit" :key="entry.revision">修订 {{entry.revision}} → {{entry.versionId}} · {{entry.createdAt}} · {{entry.actorId}}</text></template><text v-if="error" role="alert" class="error-copy">{{error}}</text><text v-if="message" role="status">{{message}}</text></view></template>
<style scoped>.content-operator,.content-preview{display:flex;flex-direction:column;gap:14px;min-width:0}.content-operator{padding-top:20px;border-top:1px solid #dce7e0}.operator-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.content-operator textarea{box-sizing:border-box;width:100%;min-height:240px;background:#f5f7f6;padding:12px;border:1px solid #ccd9d1;border-radius:12px;font-family:monospace}.content-operator text{overflow-wrap:anywhere}</style>
